var irrTask = irrigationTask.value;

irrTask.consumption = currentIrrigationWaterConsumption;
irrTask.duration = Date.now() - irrTask.startTs;

var values = {
    "irrigationTask": irrTask
};


var shouldTurnOff = false;

if (irrTask == null) {
    shouldTurnOff = true;
} else if (irrTask.durationThreshold > 0) {
    shouldTurnOff = (irrTask.startTs + irrTask.durationThreshold) < Date.now();
} else {
    shouldTurnOff = currentIrrigationWaterConsumption >= irrTask.consumptionThreshold;
}

if (shouldTurnOff) {
    values.irrigationState = "DONE";
}

return {
    "ts": irrigationTask.ts,
    "values": values
}
